const ELEMENT_PROP_KEYS = new Set(["theme","hold","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  hold: 34,
  fontFamily: "Gloock",
  scale: 1,
  delay: 0,
  speed: 1,
};

type KeepWordsElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof KeepWordsBase>;

const KeepWordsInner = forwardRef<
  HTMLDivElement,
  KeepWordsElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<KeepWords>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <KeepWordsBase
          {...(componentProps as unknown as ComponentProps<typeof KeepWordsBase>)}
        />
      </div>
    </Sequence>
  );
});

export const KeepWords = Interactive.withSchema({
  Component: KeepWordsInner,
  componentName: "<KeepWords>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
